const spellEffects=[],spellGeo=new TH.IcosahedronGeometry(.16,0);
const spellMaterials=[new TH.MeshBasicMaterial({color:0x89ddff,transparent:true,depthWrite:false}),new TH.MeshBasicMaterial({color:0xfad18b,transparent:true,depthWrite:false})];
function spellBurst(x,y,z,magic){const material=spellMaterials[magic?0:1],start=performance.now(),count=magic?24:12;for(let i=0;i<count;i++){const a=i*2.39996,spread=.5+Math.random()*1.7,velocity=new TH.Vector3(Math.cos(a)*spread,(Math.random()-.18)*2.8,Math.sin(a)*spread);const o=new TH.Mesh(spellGeo,material.clone());o.scale.setScalar(magic?.7+Math.random()*.9:.45+Math.random()*.5);o.position.set(x,y,z);scene.add(o);spellEffects.push({o,velocity,start,life:magic?750:440})}}
function spellBolt(from,to){const start=performance.now(),material=new TH.MeshBasicMaterial({color:0x8be5ff,emissive:0x000000,transparent:true,opacity:.95,depthWrite:false}),orb=new TH.Mesh(new TH.IcosahedronGeometry(.35,1),material);orb.position.copy(from);scene.add(orb);const glow=new TH.PointLight(0x69bfff,1.6,5);orb.add(glow);spellEffects.push({o:orb,start,life:360,from:from.clone(),to:to.clone(),bolt:true})}
function updateSpells(t,dt){for(let i=spellEffects.length-1;i>=0;i--){const e=spellEffects[i],p=(t-e.start)/e.life;if(p>=1){scene.remove(e.o);e.o.material.dispose();if(e.bolt){e.o.geometry.dispose();spellBurst(e.to.x,e.to.y,e.to.z,true)}spellEffects.splice(i,1);continue}if(e.bolt){e.o.position.copy(e.from).lerp(e.to,p);e.o.position.y+=Math.sin(p*Math.PI)*1.2;e.o.rotation.y+=dt*8;e.o.material.opacity=1-p*.45}else{e.o.position.addScaledVector(e.velocity,dt);e.velocity.y-=dt*3;e.o.material.opacity=Math.max(0,1-p);e.o.scale.multiplyScalar(1-dt*.8)}}}
