const mask=box(armor,c,0,3.66,.48,.92,.5,.23);for(const side of [-1,1]){const eye=mesh(armor,new TH.OctahedronGeometry(.11),m.boss?M.red:M.glow,side*.22,3.74,.65);eye.scale.set(1,.7,.5)}
