function makeTreasure(x,z,id){const g=new TH.Group();g.position.set(x,0,z);world.add(g);
const base=box(g,M.wood,0,.58,0,1.7,1.05,1.12);const lid=new TH.Group();lid.position.set(0,1.12,-.5);g.add(lid);box(lid,M.wood,0,.3,.5,1.8,.55,1.24);
for(const sx of [-.72,.72]){box(g,M.gold,sx,.55,.57,.12,1.05,.08);box(lid,M.gold,sx,.3,.5,.12,.57,1.3)}
box(g,M.gold,0,.76,.61,.35,.34,.13);const glow=mesh(g,new TH.OctahedronGeometry(.23),M.glow,0,1.53,0);glow.castShadow=false;
const chest={id,g,lid,glow,opened:!!state.treasures?.includes(id)};if(chest.opened){lid.rotation.x=-1.05;glow.visible=false}treasureChests.push(chest)}
