const minimapCanvas=document.getElementById('minimap'),mini=minimapCanvas?.getContext('2d');
function updateMiniMap(){if(!mini)return;const w=256,scale=.64;mini.clearRect(0,0,w,w);mini.fillStyle='#203b35';mini.fillRect(0,0,w,w);const px=hero.position.x,pz=hero.position.z;
const mapPoint=(x,z)=>[128+(x-px)*scale,128+(z-pz)*scale];
mini.strokeStyle='#8e8b70';mini.lineWidth=9;mini.beginPath();let [ax,az]=mapPoint(0,-170);mini.moveTo(ax,az);[ax,az]=mapPoint(0,170);mini.lineTo(ax,az);mini.stroke();
mini.strokeStyle='#a48b65';mini.lineWidth=7;mini.beginPath();[ax,az]=mapPoint(-70,-52);mini.moveTo(ax,az);[ax,az]=mapPoint(70,-52);mini.lineTo(ax,az);mini.stroke();
mini.strokeStyle='#4e9eaa';mini.lineWidth=5;mini.beginPath();for(let i=0;i<22;i++){const z=91-i*8,x=-74+Math.sin(i*.42)*7;const [u,v]=mapPoint(x,z);if(i===0)mini.moveTo(u,v);else mini.lineTo(u,v)}mini.stroke();
for(const chest of treasureChests)if(!chest.opened){const [u,v]=mapPoint(chest.g.position.x,chest.g.position.z);mini.fillStyle='#f2c766';mini.fillRect(u-2,v-2,4,4)}
for(const n of npcs){const [u,v]=mapPoint(n.x,n.z);mini.fillStyle='#ffe18d';mini.beginPath();mini.arc(u,v,3.5,0,Math.PI*2);mini.fill()}
for(const m of mobs){if(!m.alive)continue;const [u,v]=mapPoint(m.mesh.position.x,m.mesh.position.z);mini.fillStyle=m.boss?'#ef6de9':'#df6769';mini.beginPath();mini.arc(u,v,m.boss?4.5:2.5,0,Math.PI*2);mini.fill()}
mini.save();mini.translate(128,128);mini.rotate(-hero.rotation.y);mini.fillStyle='#f6f5dc';mini.strokeStyle='#2b3549';mini.lineWidth=2;mini.beginPath();mini.moveTo(0,-9);mini.lineTo(-6,7);mini.lineTo(0,3);mini.lineTo(6,7);mini.closePath();mini.fill();mini.stroke();mini.restore();
const grd=mini.createRadialGradient(128,128,70,128,128,127);grd.addColorStop(0,'#0000');grd.addColorStop(1,'#0b101de0');mini.fillStyle=grd;mini.fillRect(0,0,w,w)}
function updateQuestTracker(){const q=document.getElementById('questtracker');if(!q)return;const done=state.kills||0;q.innerHTML='<strong>✦ Abenteuer · Stufe '+state.level+'</strong><span>📜 '+(state.quests?.intro?'Auftrag erhalten':'Sprich mit Wächterin Alina')+'</span><span>⚔️ Gegner besiegt: '+done+'</span><span>📚 §34a-Wissen trainieren</span>'}
function hud(){if(!$('daycycle')){const badge=document.createElement('span');badge.id='daycycle';badge.style.cssText='display:inline-block;margin-left:9px;color:#ffe1a0;font-size:12px';$('region').appendChild(badge)}$('heroName').textContent=state.name;$('heroLevel').textContent=' · Stufe '+state.level;$('gold').textContent='🪙 '+state.gold+' Gold';$('health').firstElementChild.style.width=Math.max(0,state.hp/stats().maxhp*100)+'%';$('xp').firstElementChild.style.width=Math.min(100,state.xp/(state.level*80)*100)+'%';$('region').innerHTML=(hero.position.z< -78?'Königsstadt Drachenfels':hero.position.z>42?'Flüsterwald':'Sonnenhain')+'<small>Freie 3D-Fantasywelt · §34a-Abenteuer <span id="daycycle">☀️ Tag</span></small>'}
