function reward(xp,gold){state.gold+=gold;state.xp+=xp;while(state.xp>=state.level*80){state.xp-=state.level*80;state.level++;state.points++;state.hp=stats().maxhp;toast('⭐ Level '+state.level+' · Talentpunkt erhalten!')}save();hud()}
function attack(skill=false){const now=performance.now();if(now<(skill?skillAt:attackAt))return;if(skill)skillAt=now+3300;else attackAt=now+550;const range=skill?9:5;let target=null,d=Infinity;for(const m of mobs){if(!m.alive)continue;const dist=hero.position.distanceTo(m.mesh.position);if(dist<range&&dist<d){d=dist;target=m}}if(!target){toast('Kein Gegner in Reichweite');return}slashUntil=now+280;swordTrail.visible=true;swordTrail.position.set(hero.position.x,2.2,hero.position.z);swordTrail.rotation.y=hero.rotation.y;trailMaterial.color.set(skill?'#c9a6ff':'#c3f3ff');const damage=Math.round(stats().attack*(skill?2.5:1));target.hp-=damage;if(skill)spellBolt(new TH.Vector3(hero.position.x,2.7,hero.position.z),new TH.Vector3(target.mesh.position.x,2.5,target.mesh.position.z));else spellBurst(target.mesh.position.x,2.4,target.mesh.position.z,false);hitNumber(target,damage,skill);const ratio=Math.max(0,target.hp/target.max);target.bar.scale.x=ratio;target.bar.position.x=-(1-ratio)*1.08;const flash=sphere(scene,skill?M.glow:M.gold,target.mesh.position.x,2,target.mesh.position.z,skill?2.2:1);setTimeout(()=>scene.remove(flash),160);if(target.hp<=0){target.alive=false;target.mesh.visible=false;dungeonKill(target);reward(target.boss?240:32,target.boss?150:18);state.kills++;if(target.boss)state.boss=true;if(state.bag.length<90&&Math.random()<(target.boss?1:.42)){const item=randomItem(state.level,target.boss?3:0);state.bag.push(item);toast('🎁 '+tiers[item.rarity]+': '+item.name+' gefunden!')}else toast('⚔️ Gegner besiegt!');save()}else{toast((skill?'✨ Magie':'⚔️ Treffer')+' · '+damage+' Schaden');if(d<6){state.hp=Math.max(1,state.hp-Math.max(1,12-Math.floor(stats().defense/10)));hud()}}}
const questCases=[{title:'Jedermannsrecht',question:'Du beobachtest, wie jemand in einem Geschäft eine Ware einsteckt und ohne Bezahlung hinausgeht. Was darfst du als Sicherheitsmitarbeiter tun?',words:[['festhalten','vorläufig','127','identität'],['polizei','verständigen','rufen'],['verhältnismäßig','angemessen','erforderlich']],feedback:['Vorläufiges Festhalten unter den Voraussetzungen des §127 Abs. 1 StPO prüfen.','Polizei verständigen und Sachverhalt dokumentieren.','Verhältnismäßigkeit beachten; keine unnötige Gewalt anwenden.']},{title:'Notwehr',question:'Ein Besucher schlägt nach dir. Wie reagierst du rechtmäßig?',words:[['gegenwärtig','angriff','angreifer'],['erforderlich','abwehr','verteidigen'],['notwehr','32','stgb']],feedback:['Ein gegenwärtiger rechtswidriger Angriff muss vorliegen.','Nur die erforderliche Verteidigung einsetzen.','Rechtsgrundlage: §32 StGB (Notwehr).']},{title:'Datenschutz',question:'Eine Kollegin will Videoaufnahmen eines Vorfalls privat per Messenger verschicken. Wie gehst du vor?',words:[['nicht','verweigern','untersagen'],['datenschutz','personenbezogen','dsgvo'],['vorgesetzt','zuständig','melden']],feedback:['Private Weitergabe verhindern.','Datenschutz und Zweckbindung der Aufnahmen beachten.','Zuständige Stelle oder Vorgesetzte informieren.']}];
function assess(answer,c){const t=answer.toLowerCase();const hits=c.words.map(g=>g.some(w=>t.includes(w)));return{hits,ok:hits.filter(Boolean).length,missing:c.feedback.filter((_,i)=>!hits[i])}}
function panel(title){if(window.DrachenfelsPortraitRenderer){window.DrachenfelsPortraitRenderer.dispose();window.DrachenfelsPortraitRenderer.forceContextLoss();window.DrachenfelsPortraitRenderer=null}opened=true;$('overlay').hidden=false;const d=$('modal');d.replaceChildren();const close=document.createElement('button');close.className='close';close.textContent='✕';close.onclick=closePanel;d.append(close);const h=document.createElement('h2');h.textContent=title;d.append(h);return d}
